using J=nlohmann::json;
using U=uint64_t;
constexpr U PENDING=U(1)<<63;
struct Error:std::runtime_error{std::string code;Error(std::string c,std::string m):runtime_error(m),code(std::move(c)) {}};
[[noreturn]] static void fail(const std::string &c,const std::string &m){throw Error(c,m);}
static std::string lower(std::string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static void io_check(bool good){if(!good)fail("io_error",std::strerror(errno));}
static void writeall(int fd,const char *p,size_t n){while(n){ssize_t k=write(fd,p,n);if(k<0&&errno==EINTR)continue;io_check(k>0);p+=k;n-=k;}}
template<class T>static T load(const char *p){T v;std::memcpy(&v,p,sizeof(v));return v;}
template<class T>static void append(std::string &s,T v){s.append(reinterpret_cast<const char*>(&v),sizeof(v));}
static U hashbytes(const char *p,size_t n){U h=14695981039346656037ULL;for(size_t i=0;i<n;i++){h^=uint8_t(p[i]);h*=1099511628211ULL;}return h;}
struct MappedFile {
 int fd=-1;char *data=nullptr;U size=0;
 MappedFile()=default;MappedFile(const MappedFile&)=delete;MappedFile&operator=(const MappedFile&)=delete;
 ~MappedFile(){clear();if(fd>=0)close(fd);}
 void clear(){if(data){munmap(data,size);data=nullptr;}size=0;}
 void openfile(const std::string &p,int extra=0){fd=open(p.c_str(),O_RDWR|O_CREAT|O_CLOEXEC|extra,0600);io_check(fd>=0);remap();}
 void remap(){clear();struct stat st{};io_check(fstat(fd,&st)==0);size=st.st_size;if(size){void *p=mmap(nullptr,size,PROT_READ,MAP_SHARED,fd,0);io_check(p!=MAP_FAILED);data=(char*)p;}}
 U add(const std::string&s){U at=size;io_check(lseek(fd,0,SEEK_END)>=0);writeall(fd,s.data(),s.size());remap();return at;}
 void truncate(U n){clear();io_check(ftruncate(fd,n)==0);remap();}
};
enum Kind{INTEGER=0,TEXT=1,VECTOR=2};
struct Column{std::string name;Kind kind;size_t length;};
struct Value{Kind kind=INTEGER;int64_t integer=0;std::string text;std::vector<float> vector;};
struct Field{Kind kind=INTEGER;int64_t integer=0;std::string_view text;const char *vector=nullptr;size_t dim=0;};
static size_t utf8_count(const std::string&s){size_t n=0;for(size_t i=0;i<s.size();n++) {unsigned c=(unsigned char)s[i++];if(c<128)continue;unsigned v=0;int more=0;unsigned minimum=0;if(c>=0xc2&&c<=0xdf){v=c&31;more=1;minimum=128;}else if(c>=0xe0&&c<=0xef){v=c&15;more=2;minimum=2048;}else if(c>=0xf0&&c<=0xf4){v=c&7;more=3;minimum=65536;}else fail("invalid_value","Invalid UTF-8");for(int k=0;k<more;k++){if(i>=s.size()||((unsigned char)s[i]&192)!=128)fail("invalid_value","Invalid UTF-8 continuation");v=(v<<6)|((unsigned char)s[i++]&63);}if(v<minimum||v>0x10ffff||(v>=0xd800&&v<=0xdfff))fail("invalid_value","Invalid Unicode code point");}return n;}
struct Table {
 uint32_t id=0;std::string name;std::vector<Column> columns;size_t pk=0;int vector_col=-1;std::map<int64_t,U> rows;std::set<std::string> indexes;U generation=0,flat_generation=U(-1);MappedFile flat;size_t stride=0;
 size_t column(const std::string &n)const{std::string k=lower(n);auto dot=k.rfind('.');if(dot!=std::string::npos)k=k.substr(dot+1);for(size_t i=0;i<columns.size();i++)if(lower(columns[i].name)==k)return i;fail("unknown_column","Unknown column "+n);}
};
struct Undo{int kind;Table *table;int64_t key;U before;std::string name;};
class Database {
 std::filesystem::path dir;MappedFile wal,pending;std::map<std::string,std::unique_ptr<Table>> tables;std::map<uint32_t,Table*> ids;std::vector<Undo> undo;uint32_t next_table=1;bool transaction=false;
 static constexpr const char *MAGIC="MVDBC003",*END="COMMIT03";
public:
 explicit Database(std::filesystem::path d):dir(std::move(d)){std::filesystem::create_directories(dir);wal.openfile((dir/"data.wal").string());io_check(flock(wal.fd,LOCK_EX|LOCK_NB)==0);pending.openfile((dir/"pending.txn").string(),O_TRUNC);int fd=open(dir.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);io_check(fd>=0);int rc=fsync(fd);close(fd);io_check(rc==0);recover();for(auto &x:tables)if(!x.second->indexes.empty())flat_index(*x.second);}
 ~Database(){try{rollback_to(0);pending.truncate(0);}catch(...) {}}
 Table &table(const std::string &n){auto i=tables.find(lower(n));if(i==tables.end())fail("unknown_table","Unknown table "+n);return *i->second;}
 const char *pointer(U loc)const{U off=loc&~PENDING;const auto &f=(loc&PENDING)?pending:wal;if(off>=f.size)fail("storage_error","Invalid record offset");return f.data+off;}
 Field field(const Table&t,U loc,size_t wanted)const{const char *p=pointer(loc);for(size_t i=0;i<t.columns.size();i++){const auto &c=t.columns[i];Field v;v.kind=c.kind;if(c.kind==INTEGER){v.integer=load<int64_t>(p);p+=8;}else if(c.kind==TEXT){uint32_t n=load<uint32_t>(p);p+=4;v.text=std::string_view(p,n);p+=n;}else{v.vector=p;v.dim=c.length;p+=c.length*4;}if(i==wanted)return v;}fail("storage_error","Invalid field index");}
 std::vector<Value> decode(const Table&t,U loc)const{std::vector<Value> v;for(size_t i=0;i<t.columns.size();i++){auto f=field(t,loc,i);Value x;x.kind=f.kind;x.integer=f.integer;if(f.kind==TEXT)x.text=f.text;if(f.kind==VECTOR){x.vector.resize(f.dim);std::memcpy(x.vector.data(),f.vector,f.dim*4);}v.push_back(std::move(x));}return v;}
 std::string encode(const Table&t,const std::vector<Value>&values){std::string s;for(size_t i=0;i<t.columns.size();i++){const auto &c=t.columns[i];const auto &v=values[i];if(c.kind!=v.kind)fail("type_error","Column type mismatch");if(c.kind==INTEGER)append(s,v.integer);else if(c.kind==TEXT){if(utf8_count(v.text)>c.length)fail("value_too_long","VARCHAR limit exceeded");append(s,uint32_t(v.text.size()));s+=v.text;}else{if(v.vector.size()!=c.length)fail("dimension_mismatch","Vector dimension mismatch");for(float f:v.vector)if(!std::isfinite(f))fail("invalid_vector","Vector values must be finite float32");s.append(reinterpret_cast<const char*>(v.vector.data()),v.vector.size()*4);}}return s;}
 U record(uint8_t type,uint32_t tid,const std::string &payload){if(payload.size()>UINT32_MAX-5)fail("resource_limit","Record too large");std::string s;append(s,uint32_t(payload.size()+5));append(s,type);append(s,tid);s+=payload;return pending.add(s)+9;}
 void rollback_to(size_t point){while(undo.size()>point){Undo u=std::move(undo.back());undo.pop_back();auto &t=*u.table;if(u.kind==0){if(u.before)t.rows[u.key]=u.before;else t.rows.erase(u.key);t.generation++;}else if(u.kind==1){ids.erase(t.id);tables.erase(lower(t.name));}else {t.indexes.erase(u.name);t.generation++;}}}
 void commit(){if(!pending.size){undo.clear();return;}if(wal.size>U(INT64_MAX)-pending.size-32)fail("resource_limit","Database size exceeds implementation limit");U start=wal.size;std::string header(MAGIC,8);append(header,pending.size);append(header,hashbytes(pending.data,pending.size));io_check(lseek(wal.fd,0,SEEK_END)>=0);try{writeall(wal.fd,header.data(),header.size());writeall(wal.fd,pending.data,pending.size);writeall(wal.fd,END,8);io_check(fdatasync(wal.fd)==0);wal.remap();}catch(...){wal.truncate(start);throw;}for(auto &u:undo)if(u.kind==0){u.table->flat_generation=U(-1);auto i=u.table->rows.find(u.key);if(i!=u.table->rows.end()&&(i->second&PENDING))i->second=start+24+(i->second&~PENDING);}undo.clear();pending.truncate(0);}
 void recover(){U pos=0;while(pos+32<=wal.size){const char *p=wal.data+pos;if(std::memcmp(p,MAGIC,8))break;U n=load<U>(p+8),hash=load<U>(p+16);if(n>wal.size-pos-32)break;U end=pos+24+n;if(std::memcmp(wal.data+end,END,8)||hashbytes(p+24,n)!=hash)break;U at=pos+24;while(at<end){if(end-at<9)fail("storage_error","Malformed committed record");uint32_t len=load<uint32_t>(wal.data+at);if(len<5||len>end-at-4)fail("storage_error","Malformed committed length");uint8_t op=uint8_t(wal.data[at+4]);uint32_t tid=load<uint32_t>(wal.data+at+5);const char *body=wal.data+at+9;size_t bytes=len-5;if(op==1){J s=J::parse(body,body+bytes);auto t=std::make_unique<Table>();t->id=tid;t->name=s["name"].get<std::string>();t->pk=s["pk"].get<size_t>();for(auto &c:s["columns"]){Column col{c["name"],Kind(c["kind"].get<int>()),c["length"].get<size_t>()};if(col.kind==VECTOR)t->vector_col=t->columns.size();t->columns.push_back(std::move(col));}ids[tid]=t.get();tables[lower(t->name)]=std::move(t);next_table=std::max(next_table,tid+1);}else{auto it=ids.find(tid);if(it==ids.end())fail("storage_error","Unknown table in committed log");auto &t=*it->second;if(op==2){U loc=at+9;int64_t key=field(t,loc,t.pk).integer;t.rows[key]=loc;t.generation++;}else if(op==3){t.rows.erase(load<int64_t>(body));t.generation++;}else if(op==4)t.indexes.emplace(body,bytes);else fail("storage_error","Unknown committed operation");}at+=4+len;}pos=end+8;}if(pos!=wal.size)wal.truncate(pos);}
 void create(const std::string &name,std::vector<Column> columns,size_t pk){if(tables.count(lower(name)))fail("table_exists","Table already exists");auto t=std::make_unique<Table>();t->id=next_table++;t->name=name;t->columns=std::move(columns);t->pk=pk;J schema={{"name",name},{"pk",pk},{"columns",J::array()}};for(size_t i=0;i<t->columns.size();i++){const auto &c=t->columns[i];schema["columns"].push_back({{"name",c.name},{"kind",int(c.kind)},{"length",c.length}});if(c.kind==VECTOR)t->vector_col=i;}record(1,t->id,schema.dump());Table *ptr=t.get();tables[lower(name)]=std::move(t);ids[ptr->id]=ptr;undo.push_back({1,ptr,0,0,{}});}
 void upsert(Table&t,int64_t key,const std::string &row){auto it=t.rows.find(key);U old=it==t.rows.end()?0:it->second;U loc=record(2,t.id,row)|PENDING;undo.push_back({0,&t,key,old,{}});t.rows[key]=loc;t.generation++;}
 void erase(Table&t,int64_t key){auto it=t.rows.find(key);if(it==t.rows.end())return;std::string body;append(body,key);record(3,t.id,body);undo.push_back({0,&t,key,it->second,{}});t.rows.erase(it);t.generation++;}
 void create_index(Table&t,const std::string &name,size_t col){if(t.columns[col].kind!=VECTOR)fail("type_error","Vector index requires a vector column");if(t.indexes.count(lower(name)))fail("index_exists","Index already exists");record(4,t.id,lower(name));t.indexes.insert(lower(name));undo.push_back({2,&t,0,0,lower(name)});t.generation++;}
 void flat_index(Table&t){if(t.vector_col<0)fail("type_error","No vector column");if(t.flat_generation==t.generation&&t.flat.fd>=0)return;t.flat.clear();if(t.flat.fd>=0){close(t.flat.fd);t.flat.fd=-1;}auto path=(dir/("flat_"+std::to_string(t.id)+".idx")).string();int fd=open(path.c_str(),O_WRONLY|O_CREAT|O_TRUNC|O_CLOEXEC,0600);io_check(fd>=0);t.stride=16+4*t.columns[t.vector_col].length;std::string batch;batch.reserve(1024*1024+t.stride);for(auto [key,loc]:t.rows){auto f=field(t,loc,t.vector_col);append(batch,key);append(batch,loc);batch.append(f.vector,f.dim*4);if(batch.size()>1024*1024){writeall(fd,batch.data(),batch.size());batch.clear();}}if(!batch.empty())writeall(fd,batch.data(),batch.size());io_check(close(fd)==0);t.flat.openfile(path);t.flat_generation=t.generation;}
 J run(const std::string&sql);
 J select(class Parser &p);
 J change(class Parser &p);
 J execute(const std::string &sql){size_t save=undo.size();U offset=pending.size;try{J result=run(sql);return result;}catch(...){rollback_to(save);pending.truncate(offset);throw;}}
};
struct Token{std::string text;int kind;size_t first,last;}; // kind0 punctuation,1 identifier,2 number,3 string
class Parser {
public:
 std::string sql;std::vector<Token> tokens;size_t at=0;
 explicit Parser(std::string s):sql(std::move(s)){size_t i=0;while(i<sql.size()){unsigned char c=sql[i];if(c<=32){i++;continue;}if(c=='-'&&i+1<sql.size()&&sql[i+1]=='-'){while(i<sql.size()&&sql[i]!='\n')i++;continue;}if(c=='/'&&i+1<sql.size()&&sql[i+1]=='*'){i+=2;while(i+1<sql.size()&&!(sql[i]=='*'&&sql[i+1]=='/'))i++;if(i+1>=sql.size())fail("syntax_error","Unclosed comment");i+=2;continue;}size_t first=i;std::string text;int kind=0;if(c=='\''||c=='"'||c=='`'){char q=c;i++;bool done=false;while(i<sql.size()){char k=sql[i++];if(k==q){if(i<sql.size()&&sql[i]==q){text+=q;i++;}else{done=true;break;}}else if(k=='\\'&&i<sql.size()){char v=sql[i++];if(v=='n')text+='\n';else if(v=='r')text+='\r';else if(v=='t')text+='\t';else if(v=='0')text+='\0';else text+=v;}else text+=k;}if(!done)fail("syntax_error","Unclosed string");kind=q=='`'?1:3;}else if(std::isalpha(c)||c=='_'||c>=128){kind=1;while(i<sql.size()&&(std::isalnum((unsigned char)sql[i])||sql[i]=='_'||sql[i]=='.'||(unsigned char)sql[i]>=128))text+=sql[i++];}else if(std::isdigit(c)||((c=='-'||c=='+')&&i+1<sql.size()&&(std::isdigit((unsigned char)sql[i+1])||sql[i+1]=='.'))||(c=='.'&&i+1<sql.size()&&std::isdigit((unsigned char)sql[i+1]))){kind=2;text+=sql[i++];while(i<sql.size()&&(std::isdigit((unsigned char)sql[i])||sql[i]=='.'||sql[i]=='e'||sql[i]=='E'||((sql[i]=='+'||sql[i]=='-')&&!text.empty()&&(text.back()=='e'||text.back()=='E'))))text+=sql[i++];}else{text+=sql[i++];if(i<sql.size()&&((c=='<'&&(sql[i]=='='||sql[i]=='>'))||(c=='>'&&sql[i]=='=')||(c=='!'&&sql[i]=='=')))text+=sql[i++];}tokens.push_back({std::move(text),kind,first,i});}tokens.push_back({"",-1,sql.size(),sql.size()});}
 const Token&peek()const{return tokens[at];}
 bool is(std::string_view s)const{return lower(peek().text)==s;}
 bool accept(std::string_view s){if(is(s)){at++;return true;}return false;}
 Token take(){if(peek().kind<0)fail("syntax_error","Unexpected end of SQL");return tokens[at++];}
 void require(std::string_view s){if(!accept(s))fail("syntax_error","Expected "+std::string(s));}
 std::string ident(){auto t=take();if(t.kind!=1)fail("syntax_error","Expected identifier");return t.text;}
 void end(){accept(";");if(peek().kind!=-1)fail("unsupported_sql","Unsupported trailing SQL");}
 int64_t integer(){auto t=take();if(t.kind!=2)fail("invalid_value","Expected BIGINT");try{size_t used=0;long long v=std::stoll(t.text,&used);if(used!=t.text.size())fail("invalid_value","Expected integer");return v;}catch(const Error&){throw;}catch(...){fail("invalid_value","BIGINT overflow");}}
 size_t size(){int64_t v=integer();if(v<0)fail("invalid_value","Negative size");return size_t(v);}
 Value value(const Column&c){Value v;v.kind=c.kind;if(c.kind==INTEGER)v.integer=integer();else if(c.kind==TEXT){auto t=take();if(t.kind!=3)fail("type_error","Expected quoted string");v.text=t.text;if(utf8_count(v.text)>c.length)fail("value_too_long","VARCHAR limit exceeded");}else v.vector=vector(c.length);return v;}
 std::vector<float> vector(size_t dim){std::vector<float> values;if(peek().kind==3){auto t=take();try{J a=J::parse(t.text);if(!a.is_array())fail("invalid_vector","Expected vector array");for(auto &n:a){if(!n.is_number())fail("invalid_vector","Non-numeric vector value");double d=n.get<double>();float f=float(d);if(!std::isfinite(d)||!std::isfinite(f))fail("invalid_vector","Nonfinite float32");values.push_back(f);}}catch(const Error&){throw;}catch(...){fail("invalid_vector","Invalid vector literal");}}else{require("[");if(!accept("]")){do{auto t=take();if(t.kind!=2)fail("invalid_vector","Non-numeric vector value");try{size_t used=0;double d=std::stod(t.text,&used);float f=float(d);if(used!=t.text.size()||!std::isfinite(d)||!std::isfinite(f))fail("invalid_vector","Nonfinite float32");values.push_back(f);}catch(const Error&){throw;}catch(...){fail("invalid_vector","Invalid vector number");}}while(accept(","));require("]");}}if(dim&&values.size()!=dim)fail("dimension_mismatch","Vector dimension mismatch");return values;}
};
struct Expression{std::string name,alias,label;int column=-1;std::vector<float> query;bool distance=false;};
static Expression expression(Parser&p){Expression e;size_t start=p.peek().first;if(p.accept("l2_distance")){e.distance=true;p.require("(");e.name=p.ident();p.require(",");e.query=p.vector(0);p.require(")");e.label=p.sql.substr(start,p.tokens[p.at-1].last-start);}else{e.name=p.ident();e.label=e.name;}return e;}
struct Condition{size_t column;std::string op;Value value;};
static void condition_group(Parser&p,Table&t,std::vector<Condition>&out,int depth){if(depth>64)fail("resource_limit","Predicate nesting too deep");do{if(p.accept("(")){condition_group(p,t,out,depth+1);p.require(")");}else{auto col=t.column(p.ident());std::string op=p.take().text;if(op!="="&&op!="<"&&op!="<="&&op!=">"&&op!=">="&&op!="!="&&op!="<>")fail("unsupported_sql","Unsupported predicate");if(t.columns[col].kind==VECTOR)fail("unsupported_sql","Vector comparison is unsupported");out.push_back({col,op,p.value(t.columns[col])});}}while(p.accept("and"));}
static std::vector<Condition> conditions(Parser&p,Table&t){std::vector<Condition> out;if(p.accept("where"))condition_group(p,t,out,0);return out;}

static bool matches(Database&db,Table&t,U loc,const std::vector<Condition>&conds){for(auto &c:conds){Field f=db.field(t,loc,c.column);int cmp=0;if(f.kind==INTEGER)cmp=(f.integer>c.value.integer)-(f.integer<c.value.integer);else cmp=f.text.compare(c.value.text);if(c.op=="="?cmp!=0:c.op=="<"?cmp>=0:c.op=="<="?cmp>0:c.op==">"?cmp<=0:c.op==">="?cmp<0:cmp==0)return false;}return true;}
static J as_json(Field f){if(f.kind==INTEGER)return f.integer;if(f.kind==TEXT)return std::string(f.text);J v=J::array();for(size_t i=0;i<f.dim;i++)v.push_back(load<float>(f.vector+4*i));return v;}
static double scalar_distance(const char*p,const float*q,size_t n){double s=0;for(size_t i=0;i<n;i++){double d=double(load<float>(p+4*i))-double(q[i]);s+=d*d;}return s;}
#ifdef __x86_64__
__attribute__((target("avx2")))static double avx_distance(const char*p,const float*q,size_t n){__m256d a=_mm256_setzero_pd(),b=_mm256_setzero_pd();size_t i=0;for(;i+8<=n;i+=8){__m256d d=_mm256_sub_pd(_mm256_cvtps_pd(_mm_loadu_ps((const float*)(p+4*i))),_mm256_cvtps_pd(_mm_loadu_ps(q+i)));a=_mm256_add_pd(a,_mm256_mul_pd(d,d));d=_mm256_sub_pd(_mm256_cvtps_pd(_mm_loadu_ps((const float*)(p+4*i+16))),_mm256_cvtps_pd(_mm_loadu_ps(q+i+4)));b=_mm256_add_pd(b,_mm256_mul_pd(d,d));}alignas(32)double sums[4];_mm256_store_pd(sums,_mm256_add_pd(a,b));double s=sums[0]+sums[1]+sums[2]+sums[3];for(;i<n;i++){double d=double(load<float>(p+4*i))-double(q[i]);s+=d*d;}return s;}
#endif
static double distance(const char*p,const float*q,size_t n){
#ifdef __x86_64__
 static bool fast=__builtin_cpu_supports("avx2");if(fast)return avx_distance(p,q,n);
#endif
 return scalar_distance(p,q,n);}
struct Hit{int64_t key;U loc;double squared=0;};
J Database::select(Parser&p){bool star=p.accept("*");std::vector<Expression> exprs;if(!star){do{Expression e=expression(p);if(p.accept("as"))e.alias=p.ident();else if(p.peek().kind==1&&!p.is("from"))e.alias=p.ident();exprs.push_back(std::move(e));}while(p.accept(","));}p.require("from");Table &t=table(p.ident());if(star)for(auto &c:t.columns){Expression e;e.name=e.label=c.name;exprs.push_back(std::move(e));}for(auto &e:exprs){e.column=t.column(e.name);if(e.distance&&(t.columns[e.column].kind!=VECTOR||e.query.size()!=t.columns[e.column].length))fail("dimension_mismatch","Distance dimension mismatch");}
 auto conds=conditions(p,t);struct Order{Expression expr;bool desc;};std::vector<Order> order;if(p.accept("order")){p.require("by");do{Expression e=expression(p);if(!e.distance){for(auto &x:exprs)if(!x.alias.empty()&&lower(e.name)==lower(x.alias)){e=x;break;}}e.column=t.column(e.name);if(e.distance&&(t.columns[e.column].kind!=VECTOR||e.query.size()!=t.columns[e.column].length))fail("dimension_mismatch","Order vector dimension mismatch");bool desc=p.accept("desc");if(!desc)p.accept("asc");order.push_back({std::move(e),desc});}while(p.accept(","));}
 size_t limit=std::numeric_limits<size_t>::max(),offset=0;if(p.accept("limit")){limit=p.size();if(p.accept(",")){offset=limit;limit=p.size();}else if(p.accept("offset"))offset=p.size();}p.end();J columns=J::array();for(auto &e:exprs)columns.push_back(e.alias.empty()?e.label:e.alias);J rows=J::array();if(!limit)return {{"columns",columns},{"rows",rows}};
 bool topk=order.size()==1&&order[0].expr.distance&&!order[0].desc&&limit!=std::numeric_limits<size_t>::max();size_t keep=limit;if(topk){if(offset>SIZE_MAX-limit)fail("resource_limit","LIMIT overflow");keep=limit+offset;}std::vector<Hit> hits;auto better=[](const Hit&a,const Hit&b){return a.squared<b.squared||(a.squared==b.squared&&a.key<b.key);};std::priority_queue<Hit,std::vector<Hit>,decltype(better)> heap(better);
 auto accept=[&](int64_t key,U loc,const char *vec){if(!matches(*this,t,loc,conds))return;if(topk){auto &e=order[0].expr;double score=distance(vec?vec:field(t,loc,e.column).vector,e.query.data(),e.query.size());Hit h{key,loc,score};if(heap.size()<keep)heap.push(h);else if(better(h,heap.top())){heap.pop();heap.push(h);}}else hits.push_back({key,loc,0});};
 if(topk&&t.rows.size()>64){flat_index(t);for(U off=0;off<t.flat.size;off+=t.stride){const char *r=t.flat.data+off;accept(load<int64_t>(r),load<U>(r+8),r+16);}}else{bool exact_pk=false;int64_t key=0;for(auto &c:conds)if(c.column==t.pk&&c.op=="="){exact_pk=true;key=c.value.integer;}if(exact_pk){auto i=t.rows.find(key);if(i!=t.rows.end())accept(i->first,i->second,nullptr);}else for(auto [k,loc]:t.rows){accept(k,loc,nullptr);if(order.empty()&&limit!=SIZE_MAX&&hits.size()>=offset+limit)break;}}
 if(topk){while(!heap.empty()){hits.push_back(heap.top());heap.pop();}std::sort(hits.begin(),hits.end(),better);}else if(!order.empty())std::sort(hits.begin(),hits.end(),[&](const Hit&a,const Hit&b){for(auto &o:order){int cmp=0;if(o.expr.distance){double x=distance(field(t,a.loc,o.expr.column).vector,o.expr.query.data(),o.expr.query.size()),y=distance(field(t,b.loc,o.expr.column).vector,o.expr.query.data(),o.expr.query.size());cmp=(x>y)-(x<y);}else{auto x=field(t,a.loc,o.expr.column),y=field(t,b.loc,o.expr.column);if(x.kind==VECTOR)fail("unsupported_sql","Cannot sort vector column directly");cmp=x.kind==INTEGER?(x.integer>y.integer)-(x.integer<y.integer):x.text.compare(y.text);}if(cmp)return o.desc?cmp>0:cmp<0;}return a.key<b.key;});
 size_t bytes=0;for(size_t i=std::min(offset,hits.size());i<hits.size()&&i-offset<limit;i++){auto &h=hits[i];J row=J::array();for(auto &e:exprs){if(e.distance)row.push_back(std::sqrt(distance(field(t,h.loc,e.column).vector,e.query.data(),e.query.size())));else row.push_back(as_json(field(t,h.loc,e.column)));}bytes+=row.dump().size();if(bytes>15*1024*1024)fail("resource_limit","Result exceeds protocol response limit");rows.push_back(std::move(row));}return {{"columns",columns},{"rows",rows}};
}
J Database::run(const std::string&sql){Parser p(sql);if(p.accept("begin")||p.accept("start")){if(lower(p.tokens[p.at-1].text)=="start")p.require("transaction");p.end();if(transaction)fail("transaction_state","Transaction already active");transaction=true;return J::object();}if(p.accept("commit")){p.end();commit();transaction=false;return J::object();}if(p.accept("rollback")){p.end();rollback_to(0);pending.truncate(0);transaction=false;return J::object();}if(p.accept("select"))return select(p);
 J result=J::object();if(p.accept("create")){if(p.accept("table")){std::string name=p.ident();p.require("(");std::vector<Column> cols;std::string table_pk;size_t pk=SIZE_MAX;do{if(p.accept("primary")){p.require("key");p.require("(");table_pk=p.ident();p.require(")");continue;}Column c;c.name=p.ident();c.length=0;if(p.accept("bigint"))c.kind=INTEGER;else if(p.accept("varchar")){c.kind=TEXT;p.require("(");c.length=p.size();p.require(")");if(!c.length||c.length>UINT32_MAX)fail("invalid_schema","Invalid VARCHAR size");}else if(p.accept("vector")){c.kind=VECTOR;p.require("(");c.length=p.size();p.require(")");if(!c.length||c.length>1000000)fail("invalid_schema","Invalid vector size");}else fail("unsupported_sql","Unsupported column type");bool saw_primary=false,saw_not_null=false;while(p.is("primary")||p.is("not")){if(p.accept("primary")){p.require("key");if(pk!=SIZE_MAX||saw_primary)fail("invalid_schema","Multiple primary keys");pk=cols.size();saw_primary=true;}else{p.require("not");p.require("null");if(saw_not_null)fail("invalid_schema","Repeated NOT NULL");saw_not_null=true;}}for(auto &x:cols)if(lower(x.name)==lower(c.name))fail("invalid_schema","Duplicate column");cols.push_back(std::move(c));}while(p.accept(","));p.require(")");p.end();if(!table_pk.empty()){if(pk!=SIZE_MAX)fail("invalid_schema","Multiple primary keys");for(size_t i=0;i<cols.size();i++)if(lower(cols[i].name)==lower(table_pk))pk=i;}if(pk==SIZE_MAX||cols[pk].kind!=INTEGER)fail("invalid_schema","Exactly one BIGINT primary key is required");if(std::count_if(cols.begin(),cols.end(),[](const Column&c){return c.kind==VECTOR;})>1)fail("invalid_schema","At most one vector column");create(name,std::move(cols),pk);}else if(p.accept("vector")){p.require("index");std::string name=p.ident();p.require("on");Table&t=table(p.ident());p.require("(");size_t col=t.column(p.ident());p.require(")");p.end();create_index(t,name,col);}else fail("unsupported_sql","Unsupported CREATE");}
 else if(p.accept("insert")){p.require("into");Table&t=table(p.ident());std::vector<size_t> cols;if(p.accept("(")){do{cols.push_back(t.column(p.ident()));}while(p.accept(","));p.require(")");}else for(size_t i=0;i<t.columns.size();i++)cols.push_back(i);std::set<size_t> unique(cols.begin(),cols.end());if(cols.size()!=t.columns.size()||unique.size()!=cols.size())fail("invalid_value","Every column must be supplied exactly once");p.require("values");std::vector<std::pair<int64_t,std::string>> parsed;std::set<int64_t> keys;do{p.require("(");std::vector<Value> values(t.columns.size());for(size_t i=0;i<cols.size();i++){if(i)p.require(",");values[cols[i]]=p.value(t.columns[cols[i]]);}p.require(")");int64_t key=values[t.pk].integer;if(t.rows.count(key)||!keys.insert(key).second)fail("duplicate_key","Duplicate primary key");parsed.emplace_back(key,encode(t,values));}while(p.accept(","));p.end();for(auto &x:parsed)upsert(t,x.first,x.second);result["affected_rows"]=parsed.size();}
 else if(p.accept("update")){Table&t=table(p.ident());p.require("set");std::vector<std::pair<size_t,Value>> assign;do{size_t col=t.column(p.ident());if(col==t.pk)fail("unsupported_sql","Primary key updates are unsupported");p.require("=");assign.emplace_back(col,p.value(t.columns[col]));}while(p.accept(","));auto conds=conditions(p,t);p.end();size_t changed=0;for(auto [key,loc]:t.rows)if(matches(*this,t,loc,conds)){auto values=decode(t,loc);for(auto &a:assign)values[a.first]=a.second;upsert(t,key,encode(t,values));changed++;}result["affected_rows"]=changed;}
 else if(p.accept("delete")){p.require("from");Table&t=table(p.ident());auto conds=conditions(p,t);p.end();std::vector<int64_t> keys;for(auto [key,loc]:t.rows)if(matches(*this,t,loc,conds))keys.push_back(key);for(auto k:keys)erase(t,k);result["affected_rows"]=keys.size();}
 else fail("unsupported_sql","Unsupported SQL statement");if(!transaction)commit();return result;
}
int main(int argc,char **argv){std::ios::sync_with_stdio(false);std::cin.tie(nullptr);std::string dir="/data";for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--data-dir"&&i+1<argc)dir=argv[++i];else if(a.rfind("--data-dir=",0)==0)dir=a.substr(11);else{std::cerr<<"Unknown argument\n";return 2;}}try{Database db(dir);std::cout<<"{\"type\":\"ready\"}\n"<<std::flush;std::string line;while(std::getline(std::cin,line)){J id=nullptr,response;try{J request=J::parse(line);if(!request.is_object()||!request.contains("id")||!request.contains("op"))fail("protocol_error","Missing id/op");id=request["id"];if(request["op"]=="shutdown"){db.run("ROLLBACK;");std::cout<<J({{"id",id},{"ok",true}}).dump()<<'\n'<<std::flush;return 0;}if(request["op"]!="execute"||!request.contains("sql")||!request["sql"].is_string())fail("protocol_error","Expected execute with SQL");if(request.contains("search_mode")&&request["search_mode"]!="exact"&&request["search_mode"]!="ann")fail("protocol_error","Unknown search mode");response=db.execute(request["sql"].get<std::string>());response["id"]=id;response["ok"]=true;}catch(const Error&e){response={{"id",id},{"ok",false},{"error",{{"code",e.code},{"message",e.what()}}}};}catch(const std::exception&e){response={{"id",id},{"ok",false},{"error",{{"code","invalid_input"},{"message",e.what()}}}};}std::cout<<response.dump()<<'\n'<<std::flush;}}catch(const std::exception&e){std::cerr<<"Startup failed: "<<e.what()<<'\n';return 1;}return 0;}
